export(asset_correlation)
export(capital_k)
export(rwa)
export(effective_maturity)

rwa <- function(k, ead) {
  k * 12.5 * ead
}

effective_maturity <- function(m) {
  pmin(pmax(m, 1), 5)
}

asset_correlation <- function(pd) {
  w <- (1 - exp(-50 * pd)) / (1 - exp(-50))
  0.12 * w + 0.24 * (1 - w)
}

